pub fn edit(a: Str, b: Str) -> Int {
  let ca = a.chars()
  let cb = b.chars()
  let n = ca.len()
  let m = cb.len()
  var prev: List[Int] = []
  for j in range(0, m + 1) {
    prev = prev.push(j)
  }
  for i in range(1, n + 1) {
    var cur: List[Int] = [i]
    let ai = ca.get_or(i - 1, "")
    for j in range(1, m + 1) {
      var cost = 1
      if ai == cb.get_or(j - 1, "") {
        cost = 0
      }
      let best = (prev.get_or(j, 0) + 1).min(cur.get_or(j - 1, 0) + 1).min(prev.get_or(j - 1, 0) + cost)
      cur = cur.push(best)
    }
    prev = cur
  }
  return prev.get_or(m, 0)
}
